/**
 * Per-request CSP nonce generator.
 *
 * Emits a 128-bit random value as a base64url string — short enough to
 * keep response headers small and long enough to satisfy the
 * CSP "strict-dynamic" guidance (RFC 5.3, §2). Uses the Web Crypto API
 * available in Edge runtimes, Workers and modern Node.
 *
 * The nonce is generated by the Edge proxy on every request
 * (`src/proxy.ts`) and propagated to server components through the
 * `x-nonce` request header so `<style>` and `<script>` tags rendered
 * server-side can reuse it.
 *
 * NOTE: this module does NOT declare `import 'server-only'` because its
 * sole consumer on the client surface is the unit test suite (jsdom),
 * and `server-only`'s client-side shim throws at import time, which
 * would break the test runner. The nonce generator is pure (no
 * side-effect at import) so shipping it to the client bundle is
 * harmless; the `x-nonce` header is what matters for the CSP chain.
 *
 * @see Req 25.3 — strict CSP with per-request nonces.
 *
 * Task 10.1.
 */

const NONCE_BYTE_LENGTH = 16;

/**
 * Generate a fresh 128-bit nonce as a URL-safe base64 string without
 * padding.
 *
 * The function uses `crypto.getRandomValues`, which is available in
 * every supported runtime (Cloudflare Workers, Node ≥ 20, modern
 * browsers). It never throws in the supported runtimes — if the API
 * is missing, we want the error to surface loudly rather than fall
 * back to a weak source.
 */
export function generateNonce(): string {
  const bytes = new Uint8Array(NONCE_BYTE_LENGTH);
  crypto.getRandomValues(bytes);
  return encodeBase64Url(bytes);
}

/**
 * Minimal base64url encoder — avoids the Node-only `Buffer` API so the
 * module stays runnable in Edge runtimes.
 */
function encodeBase64Url(bytes: Uint8Array): string {
  let binary = '';
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  // `btoa` is provided by the Web standard library across all supported
  // runtimes (Workers, Edge, Node 20+).
  const base64 =
    typeof btoa === 'function' ? btoa(binary) : Buffer.from(binary, 'binary').toString('base64');
  return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/u, '');
}
